solution:
import copy


def snapshot(config):
    """Return a record of config that later edits to config cannot affect."""
    return copy.deepcopy(config)

def relabel(row: tuple[str, int], name: str) -> tuple[str, int]:
    """Return the row with its first field replaced by name."""
    return (name, *row[1:])


print(relabel(("a", 1), "b"))

